css:
.h1 { display: flex; align-items: center; justify-content: space-between; width: 920px; padding: 18px 28px; box-sizing: border-box; background: #fff; border-bottom: 1px solid #e5e7eb; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.h1-logo { font-size: 22px; font-weight: 800; color: #111827; text-decoration: none; letter-spacing: 0.5px; }
.h1-nav { display: flex; gap: 28px; }
.h1-nav a { font-size: 14px; color: #4b5563; text-decoration: none; }
.h1-nav a:hover { color: #111827; }

.h2 { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; width: 920px; padding: 22px 28px; box-sizing: border-box; background: #fff; border-bottom: 1px solid #e5e7eb; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.h2-left, .h2-right { display: flex; gap: 22px; }
.h2-right { justify-content: flex-end; }
.h2 a { font-size: 13px; color: #374151; text-decoration: none; letter-spacing: 0.5px; }
.h2-logo { font-size: 26px !important; font-weight: 300; letter-spacing: 8px !important; color: #111827 !important; }

.h3 { display: flex; align-items: center; gap: 36px; width: 920px; padding: 14px 28px; box-sizing: border-box; background: #fff; border-bottom: 1px solid #e5e7eb; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.h3-logo { display: flex; align-items: center; gap: 8px; font-size: 18px; font-weight: 800; color: #111827; text-decoration: none; }
.h3-mark { width: 22px; height: 22px; border-radius: 6px; background: linear-gradient(135deg, #6366f1, #ec4899); }
.h3-nav { display: flex; flex: 1; gap: 26px; }
.h3-nav a { font-size: 14px; color: #4b5563; text-decoration: none; }
.h3-actions { display: flex; align-items: center; gap: 14px; }
.h3-login { font-size: 14px; color: #374151; text-decoration: none; }
.h3-signup { padding: 9px 18px; border-radius: 8px; background: #4f46e5; color: #fff; font-size: 14px; font-weight: 600; text-decoration: none; }
.h3-signup:hover { background: #4338ca; }

.h4 { display: flex; align-items: center; gap: 28px; width: 920px; padding: 14px 28px; box-sizing: border-box; background: #fff; border-bottom: 1px solid #e5e7eb; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.h4-logo { font-size: 20px; font-weight: 800; color: #e11d48; text-decoration: none; }
.h4-search { display: flex; flex: 1; align-items: center; gap: 8px; padding: 0 16px; background: #f3f4f6; border-radius: 999px; }
.h4-input { flex: 1; height: 40px; border: 0; background: transparent; font-size: 14px; outline: none; }
.h4-icons { display: flex; gap: 18px; }
.h4-icons a { font-size: 13px; color: #374151; text-decoration: none; white-space: nowrap; }

.h5 { display: flex; align-items: center; justify-content: space-between; width: 920px; padding: 18px 28px; box-sizing: border-box; background: #111827; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.h5-logo { font-size: 20px; font-weight: 800; color: #f9fafb; text-decoration: none; letter-spacing: 2px; }
.h5-logo span { color: #22d3ee; }
.h5-nav { display: flex; gap: 26px; }
.h5-nav a { padding-bottom: 4px; border-bottom: 2px solid transparent; font-size: 14px; color: #9ca3af; text-decoration: none; }
.h5-nav a:hover, .h5-nav a.is-active { border-bottom-color: #22d3ee; color: #f9fafb; }

.h6 { width: 360px; background: #fff; border: 1px solid #e5e7eb; border-radius: 12px; overflow: hidden; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.h6-check { position: absolute; opacity: 0; pointer-events: none; }
.h6-bar { display: flex; align-items: center; justify-content: space-between; padding: 14px 18px; }
.h6-logo { font-size: 18px; font-weight: 800; color: #111827; text-decoration: none; }
.h6-burger { display: flex; flex-direction: column; justify-content: center; gap: 5px; width: 40px; height: 40px; padding: 0 9px; box-sizing: border-box; border-radius: 8px; cursor: pointer; }
.h6-burger:hover { background: #f3f4f6; }
.h6-burger span { display: block; height: 2px; background: #111827; border-radius: 2px; transition: transform 0.2s, opacity 0.2s; }
.h6-menu { display: none; flex-direction: column; border-top: 1px solid #e5e7eb; }
.h6-menu a { padding: 14px 18px; border-bottom: 1px solid #f1f5f9; font-size: 14px; color: #374151; text-decoration: none; }
.h6-check:checked ~ .h6-menu { display: flex; }
.h6-check:checked ~ .h6-bar .h6-burger span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.h6-check:checked ~ .h6-bar .h6-burger span:nth-child(2) { opacity: 0; }
.h6-check:checked ~ .h6-bar .h6-burger span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

.h7 { width: 920px; background: #fff; border-bottom: 1px solid #e5e7eb; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.h7-top { display: flex; justify-content: space-between; padding: 8px 28px; background: #111827; font-size: 12px; color: #e5e7eb; }
.h7-top-links { display: flex; gap: 18px; }
.h7-top a { color: #e5e7eb; text-decoration: none; }
.h7-main { display: flex; align-items: center; gap: 36px; padding: 16px 28px; }
.h7-logo { font-size: 22px; font-weight: 800; color: #111827; text-decoration: none; letter-spacing: 2px; }
.h7-nav { display: flex; flex: 1; gap: 24px; }
.h7-nav a { font-size: 14px; color: #374151; text-decoration: none; }
.h7-nav a:last-child { color: #dc2626; font-weight: 700; }
.h7-cart { padding: 8px 16px; border: 1px solid #111827; border-radius: 999px; font-size: 13px; color: #111827; text-decoration: none; }

.h8-stage { width: 920px; padding: 18px 20px 70px; box-sizing: border-box; background: linear-gradient(120deg, #6366f1, #ec4899 60%, #f59e0b); border-radius: 12px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.h8 { display: flex; align-items: center; justify-content: space-between; padding: 12px 22px; background: rgba(255, 255, 255, 0.22); border: 1px solid rgba(255, 255, 255, 0.4); border-radius: 999px; -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px); }
.h8-logo { font-size: 18px; font-weight: 800; color: #fff; text-decoration: none; }
.h8-nav { display: flex; align-items: center; gap: 24px; }
.h8-nav a { font-size: 14px; color: #fff; text-decoration: none; }
.h8-cta { padding: 8px 18px; border-radius: 999px; background: #fff; color: #4338ca !important; font-weight: 700; }
